use rk3588_boot_support::{DelayUs,Mmio32,Mmio8};
pub const DDR_PROBE_BASE:u64=0xFECC_0000;pub trait DdrTrainer{type Error;fn train(&mut self,probe_byte:u8)->Result<(),Self::Error>;}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum DdrSequenceError<E>{Training(E)}
pub fn run_ddr_probe_and_train<I:Mmio32+Mmio8+DelayUs,T:DdrTrainer>(io:&mut I,trainer:&mut T)->Result<u8,DdrSequenceError<T::Error>>{io.write32(DDR_PROBE_BASE+0x84,15);io.write32(DDR_PROBE_BASE+0x04,50_856_192);io.write32(DDR_PROBE_BASE+0x08,1);let mut status=15u32;let mut left=10_001u32;let mut probe=0u8;loop{if status&3==3{io.write32(DDR_PROBE_BASE+0x84,3);probe=io.read8(DDR_PROBE_BASE+0x22);break}status=io.read32(DDR_PROBE_BASE+0x84);left-=1;if left==0{break}io.delay_us(1)}trainer.train(probe).map_err(DdrSequenceError::Training)?;Ok(probe)}
#[cfg(test)]mod tests{use super::*;struct I{status:u32,probe:u8}impl Mmio32 for I{fn read32(&mut self,a:u64)->u32{if a==DDR_PROBE_BASE+0x84{self.status}else{0}}fn write32(&mut self,a:u64,v:u32){if a==DDR_PROBE_BASE+0x84&&v==15{self.status=3}}}impl Mmio8 for I{fn read8(&mut self,a:u64)->u8{if a==DDR_PROBE_BASE+0x22{self.probe}else{0}}}impl DelayUs for I{fn delay_us(&mut self,_:u32){}}struct T(u8);impl DdrTrainer for T{type Error=();fn train(&mut self,p:u8)->Result<(),()>{self.0=p;Ok(())}}#[test]fn sequence(){let mut i=I{status:0,probe:0x77};let mut t=T(0);assert_eq!(run_ddr_probe_and_train(&mut i,&mut t),Ok(0x77));assert_eq!(t.0,0x77);}}
